{
  "name": "@a4hgehad/weave-mcp",
  "version": "0.10.0",
  "description": "Weave — lean OpenCode plugin with multi-agent orchestration + MCP support",
  "author": "3r3bu5",
  "license": "MIT",
  "homepage": "https://github.com/3r3bu5/opencode-weave#readme",
  "repository": {
    "type": "git",
    "url": "https://github.com/3r3bu5/opencode-weave.git"
  },
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist/"
  ],
  "scripts": {
    "build": "bun run script/build.ts && tsc --emitDeclarationOnly",
    "clean": "rm -rf dist",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "eval": "bun run script/eval.ts",
    "eval:smoke": "bun run script/eval.ts --suite prompt-smoke",
    "eval:phase2": "bun run script/eval.ts --suite agent-routing",
    "eval:coverage": "bun run script/verify-eval-coverage.ts",
    "eval:spike": "bun run script/eval-spike-github-models.ts",
    "eval:trend": "bun run script/eval-trend-report.ts"
  },
  "keywords": [
    "opencode",
    "plugin",
    "agents",
    "weave"
  ],
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.3.3",
    "@opencode-ai/sdk": "^1.3.3",
    "jsonc-parser": "^3.3.1",
    "picocolors": "^1.1.1",
    "zod": "^4.0.0"
  },
  "devDependencies": {
    "bun": "^1.3.11",
    "bun-types": "^1.3.11",
    "typescript": "^6.0.2"
  }
}
